+void PartialArrayStateAllocator::reset() {
+  _free_list = nullptr;
+  // Restore the arena to its freshly constructed state, i.e. destructor-then-constructor.
+  _arena.~Arena();
+  ::new (&_arena) Arena(mtGC);
